import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  describe("quote — base premiums", () => {
    it.todo("empty item list → premium 5 G (only the processing fee)");
    it.todo("a single sword → base premium 100 G");
    it.todo("a single amulet → base premium 60 G");
    it.todo("a single staff → base premium 80 G");
    it.todo("a single potion → base premium 40 G");
    it.todo("a single rune → base premium 25 G");
    it.todo("a single moonstone → base premium 25 G");
  });

  describe("quote — building block of 3 alike components", () => {
    it.todo("2 runes → 50 G base premium");
    it.todo("3 runes → 60 G base premium (block applies)");
    it.todo("4 runes → 100 G base premium (no block — block requires exactly 3)");
    it.todo("7 runes → 175 G base premium");
    it.todo("2 runes + 1 moonstone → 75 G base premium (no block: different types)");
    it.todo("3 runes + 3 moonstones → 120 G base premium (two separate blocks)");
  });

  describe("quote — item-specific modifiers", () => {
    it.todo("a cursed sword adds a 50 % surcharge on its own base premium");
    it.todo("a sword with enchantment exactly 5 adds a 30 % surcharge");
    it.todo("a sword with enchantment 4 adds no high-enchantment surcharge");
    it.todo("a cursed sword with enchantment exactly 5 gets both surcharges");
    it.todo(
      "a cursed sword (100 G) plus a plain amulet (60 G) → curse adds 50 G on the sword only, 210 G before further modifiers and fee",
    );
  });

  describe("quote — policy-wide modifiers", () => {
    it.todo("a customer with exactly 2 years with MHPCO receives the 20 % loyalty discount");
    it.todo("a customer with 1 year with MHPCO receives no loyalty discount");
    it.todo("every quote carries the 10 % first insurance surcharge");
    it.todo("the second quote in a scenario receives the 15 % follow-up contract discount");
    it.todo("a 5 G processing fee is added to every premium");
  });

  describe("quote — rounding in the MHPCO's favour", () => {
    it.todo("a premium calculation yielding 197.5 G → final premium 198 G (rounded up)");
    it.todo("intermediate amounts are kept as fractions; only the final premium is rounded");
  });

  describe("quote — integration examples", () => {
    it.todo("newcomer (0 years, no previous contract) with a cursed steel sword, enchantment 3 → premium 165 G");
    it.todo(
      "long-standing customer (3 years), second quote, cursed steel sword enchantment 7 → premium 160 G",
    );
  });

  describe("claim — standard reimbursement", () => {
    it.todo("regular steel sword, enchantment 3, damage 500 G → payout 400 G");
    it.todo("damage to a rune, damage 200 G → payout 100 G (no enchantment or material)");
  });

  describe("claim — special clauses", () => {
    it.todo("steel sword, enchantment 9, damage 1000 G → payout 400 G (50 % then deductible)");
    it.todo("dragon-material sword, enchantment 5, damage 800 G → payout 700 G (full, then deductible)");
    it.todo("dragon-material sword, enchantment 9, damage 1000 G → payout 400 G (50 % rule wins)");
    it.todo("dragon-material sword, enchantment exactly 8, damage 1000 G → payout 400 G");
  });

  describe("claim — deductible per damage event", () => {
    it.todo("a dragon attack damaging a sword (500 G) and an amulet (300 G) → payout 600 G");
  });

  describe("claim — payout rounding", () => {
    it.todo("a payout calculation yielding 350.5 G → final payout 350 G (rounded down)");
  });

  describe("claim — insurance sum and cap", () => {
    it.todo("a policy covering a sword and an amulet → insurance sum 1600 G, cap 3200 G");
    it.todo("a policy covering a cursed sword → cap 2000 G (premium modifiers do not raise the cap)");
    it.todo("a policy covering a sword and 3 runes → insurance sum 1750 G (block discount does not lower the sum)");
    it.todo("a policy covering two swords → insurance sum 2000 G, cap 4000 G");
  });

  describe("claim — cap exhaustion across successive claims", () => {
    it.todo("sword policy (cap 2000 G), first claim of 1500 G → payout 1400 G, remainingCap 600 G");
    it.todo("sword policy (cap 2000 G), second claim of 1500 G → payout 600 G, remainingCap 0 G");
  });

  describe("claim — multiple items of the same type", () => {
    it.todo(
      "two swords insured, two sword damage entries → each entry is a separate damage with its own deductible",
    );
    it.todo("more damage entries of a type than the policy covers → the claim is rejected");
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (e.g. broomstick) → error, no results");
    it.todo("claim referencing an item not part of the policy (amulet when only a sword is insured) → error");
    it.todo("claim referencing a damage entry with an unknown item type → error");
    it.todo("claim containing a damage entry with amount -200 → error");
  });

  describe("CLI", () => {
    it.todo("reads a scenario from stdin and writes {results: [...]} to stdout");
    it.todo("the schema example (5-year customer, amulet quote then amulet claim of 200 G) produces two results");
    it.todo("exits with a non-zero status and writes to stderr when the scenario is invalid");
  });
});

