    );
    it.todo("more damage entries of a type than the policy covers → the claim is rejected");
  });

  describe("errors", () => {
    it.todo("quote with an unknown item type (e.g. broomstick) → error, no results");
    it.todo("claim referencing an item not part of the policy (amulet when only a sword is insured) → error");
    it.todo("claim referencing a damage entry with an unknown item type → error");
    it.todo("claim containing a damage entry with amount -200 → error");
