const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// A building block of 3 alike components is offered at a special base premium.
const sumBasePremiums = (items: Item[]): number => {
  let total = 0;
  for (const [type, count] of countByType(items)) {
    total =
      count === COMPONENT_BLOCK_SIZE
        ? total + COMPONENT_BLOCK_PREMIUM
        : total + count * basePremiumFor({ type });
  }
  return total;
};

