export type InsurableItemType = keyof typeof BASE_PREMIUMS;

const basePremiumForType = (type: string): number =>
  BASE_PREMIUMS[type as InsurableItemType];

const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

const countByType = (items: Item[]): Map<string, number> => {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  return counts;
};

// Items of one type, quoted together. A group of exactly 3 forms a building
// block and is offered at a flat base premium; any other size is priced per
// item. "Alike" means the same item type — 2 runes + 1 moonstone is two
// groups, so neither is a block.
type AlikeGroup = [type: string, count: number];

const isBuildingBlock = ([, count]: AlikeGroup): boolean =>
  count === BLOCK_SIZE;

const basePremiumForGroup = (group: AlikeGroup): number => {
  const [type, count] = group;
  return isBuildingBlock(group)
    ? BLOCK_PREMIUM
    : count * basePremiumForType(type);
};

const sumBasePremiums = (items: Item[]): number =>
  [...countByType(items)].reduce(
    (total, group) => total + basePremiumForGroup(group),
    0,
  );

// Premiums are rounded up, in the MHPCO's favour; only the final premium is
// rounded, intermediate amounts stay fractional.
const roundInMHPCOsFavour = Math.ceil;

const quotePremium = (items: Item[]): number => {
  const basePremium = sumBasePremiums(items);
  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
  return roundInMHPCOsFavour(
    basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
  );
};

const runStep = (step: Step): QuoteResult | ClaimResult => {
  switch (step.op) {
    case "quote":
      return { premium: quotePremium(step.items) };
    case "claim":
      throw new Error("claim steps are not supported yet");
  }
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map(runStep),
});

