): number => basePremium * policyModifierRateFor(customer, precedingContracts);

const quotePremium = (
  items: Item[],
  customer: Customer,
  precedingContracts: number,
): number => {
  const basePremium = sumBasePremiums(items);
  const itemSurcharges = sumItemSurcharges(items);
  const policyModifier = policyModifierFor(
    basePremium,
    customer,
    precedingContracts,
  );
  return roundInMHPCOsFavour(
    basePremium + itemSurcharges + policyModifier + PROCESSING_FEE,
  );
};

const runStep = (step: Step, customer: Customer): QuoteResult | ClaimResult => {
  switch (step.op) {
    case "quote":
      return { premium: quotePremium(step.items, customer) };
    case "claim":
      throw new Error("claim steps are not supported yet");
  }
};

export const runScenario = (scenario: Scenario): ScenarioResults => ({
  results: scenario.steps.map((step) => runStep(step, scenario.customer)),
});

