// An item's insured worth, distinct from what it costs to insure.
const INSURANCE_VALUES = {
  sword: 1000,
  amulet: 600,
  staff: 800,
  potion: 400,
  rune: 250,
  moonstone: 250,
} as const satisfies Record<InsurableItemType, number>;

const insuranceValueForType = (type: string): number =>
  INSURANCE_VALUES[type as InsurableItemType];

const DEDUCTIBLE = 100;
const CAP_MULTIPLE = 2;

// A quote step creates a policy; later claim steps refer to it by that step's
// index. The cap is consumed as claims are paid.
interface Policy {
  items: Item[];
  remainingCap: number;
}

const openPolicy = (items: Item[]): Policy => ({
  items,
  remainingCap:
    CAP_MULTIPLE *
    items.reduce((sum, item) => sum + insuranceValueForType(item.type), 0),
});

// The deductible applies once per damage event, not once per claim.
const payoutForDamage = (damage: Damage): number => damage.amount - DEDUCTIBLE;

const settleClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
  const payout = damages.reduce(
    (total, damage) => total + payoutForDamage(damage),
    0,
  );
  policy.remainingCap -= payout;
  return { payout, remainingCap: policy.remainingCap };
};

const runStep = (
  step: Step,
  customer: Customer,
  precedingContracts: number,
  policies: Map<number, Policy>,
  stepIndex: number,
): QuoteResult | ClaimResult => {
  switch (step.op) {
    case "quote":
      policies.set(stepIndex, openPolicy(step.items));
      return { premium: quotePremium(step.items, customer, precedingContracts) };
    case "claim":
      return settleClaim(policies.get(step.policy)!, step.incident.damages);
  }
};

